        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:12:40\"\n    },\n    \"flatsome-child::header_elements_left\": {\n        \"value\": [\n            \"search-form\"\n        ],\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:13:40\"\n    },\n    \"flatsome-child::site_logo\": {\n        \"value\": 536,\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:13:40\"\n    },\n    \"flatsome-child::search_icon_style\": {\n        \"value\": \"fill-round\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:22:52\"\n    },\n    \"flatsome-child::header_search_width\": {\n        \"value\": \"89\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:25:52\"\n    },\n    \"flatsome-child::header_elements_bottom_right\": {\n        \"value\": [],\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:15:40\"\n    },\n    \"flatsome-child::header_search_style\": {\n        \"value\": \"dropdown\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:22:52\"\n    },\n    \"flatsome-child::header_search_categories\": {\n        \"value\": false,\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:15:40\"\n    },\n    \"flatsome-child::header_search_form_style\": {\n        \"value\": \"flat\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:22:52\"\n    },\n    \"flatsome-child::header_bg_img_repeat\": {\n        \"value\": \"no-repeat\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-04-11 08:21:52\"\n    },\n    \"flatsome-child::html_after_header\": {\n        \"value